  ('0a3bc1d6-05d0-4ff5-a1b0-c2bc730ec1d4', '0f4a1f11-7f6f-44b6-9212-8f41f9d9ce80', 'ProjectSphere', 'A premium project discovery hub for student and developer communities.', 'Productivity', JSON_ARRAY('React','Node.js','MySQL','Vite'), 'A community-powered platform for discovering, publishing, and reviewing technical projects.', 'ProjectSphere brings together project publishing, thoughtful reviews, and profile-driven discovery. It is designed for students, founders, and AI researchers looking to share technical work and get actionable feedback.',NULL,NULL,'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1200&q=80', 0, 0, 'featured'),
  ('2df9fdc9-8aa2-4fe8-a29d-17d3670d9ef1', '19d7f4d5-9bcc-4d55-84d9-6ce2b1170dd7', 'SignalCare AI', 'Diagnose patient risk patterns with explainable machine learning.', 'AI/ML', JSON_ARRAY('Python','PyTorch','FastAPI'), 'An explainable AI system for clinical risk scoring and patient recommendation workflows.', 'SignalCare AI supports healthcare teams by surfacing evidence from multimodal records and ranking potential intervention pathways. The platform emphasizes interpretability and needs-driven design.',NULL,NULL,'https://images.unsplash.com/photo-1576091160550-2173dba999ef?auto=format&fit=crop&w=1200&q=80', 0, 0, 'published'),
  ('4b0ec30d-1d0c-4fb8-a91f-7d2285d5d109', '0f4a1f11-7f6f-44b6-9212-8f41f9d9ce80', 'PulseBoard', 'A thoughtful dashboard for shipping healthier team rituals.', 'Productivity', JSON_ARRAY('React','Node.js','SQLite'), 'A collaborative planning tool designed to help small teams turn goals into visible weekly momentum.', 'PulseBoard combines goal tracking, sprint planning, and team check-ins in one calm workspace tailored for distributed product teams.', 'https://github.com/example/pulseboard', 'https://pulseboard.example.com', 'https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1200&q=80', 0, 0, 'featured'),
  ('7f6a8d39-07f8-4db9-a630-3fc14b87f84e', '19d7f4d5-9bcc-4d55-84d9-6ce2b1170dd7', 'AgriSense AI', 'AI field signals for smarter crop health decisions.', 'AI/ML', JSON_ARRAY('Python','TensorFlow','FastAPI'), 'An explainable crop-monitoring workflow that blends satellite imagery and in-field sensor data to flag stress early.', 'AgriSense AI helps growers act on environmental anomalies quickly by highlighting at-risk plots and summarizing what changed over time.', 'https://github.com/example/agrisense-ai', 'https://agrisense.example.com', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1200&q=80', 0, 0, 'published'),
  ('a81d96d0-bf40-412e-bd5d-b66877f9b0f6', '0f4a1f11-7f6f-44b6-9212-8f41f9d9ce80', 'CodeCanvas', 'Design, prototype, and review product ideas faster.', 'Developer Tools', JSON_ARRAY('TypeScript','Vite','Node.js'), 'A lightweight studio for collecting design ideas, organizing notes, and turning them into interactive prototypes.', 'CodeCanvas is a concept playground for product teams that need to sketch flows, test ideas, and collect feedback without leaving the browser.', 'https://github.com/example/codecanvas', 'https://codecanvas.example.com', 'https://images.unsplash.com/photo-1461749280684-dccba630e2f6?auto=format&fit=crop&w=1200&q=80', 0, 0, 'published');
